// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the sender address and an arbitrary vector length seed
    function testFuzz_property(address from, uint256 nonce) public {
        // keep domain reasonable: from must be non-zero (admissible caller)
        vm.assume(from != address(0));
        // build a non-empty array of addresses (size between 1 and 8 to keep test lightweight)
        uint256 len = 1 + (nonce % 8);
        address[] memory tos = new address[](len);
        // deploy a recording helper that exposes the exact transferFrom signature
        Recorder rec = new Recorder();
        for (uint i = 0; i < len; i++) {
            // vary recipient addresses so calls differ per iteration
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, nonce, i)))));
        }

        // Call transfer on c, routing calls to our Recorder. The reference implementation
        // will call Recorder.transferFrom for every element in tos; the mutant may skip the first.
        bool ok;
        try c.transfer(from, address(rec), tos, 123) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any non-empty tos, c must have invoked the callee exactly tos.length times.
        // We observe that by reading the Recorder's public callCount getter (it records each call).
        // This should hold for the correct contract for ALL inputs; the mutant that starts loop at i=1
        // will make only len-1 calls when len>0, causing this assertion to fail for some fuzzed inputs.
        assertTrue(ok && rec.callCount() == len);
    }
}

// Recording helper that matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
contract Recorder {
    uint256 public callCount;
    // store last decoded arguments for extra observability (not used in assert)
    address[] public addrsFrom;
    address[] public addrsTo;
    uint256[] public vals;

    // function that matches the encoded selector and records the call
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        callCount += 1;
        addrsFrom.push(from);
        addrsTo.push(to);
        vals.push(v);
        return true;
    }
}
